    const data = source.data;
    const n = data["n"];

    const name = select.value;
    const A = amp_slider.value;
    const N = period_slider.value;

    const x = [];
    const x_shift = [];

    for (let i = 0; i < n.length; i++) {
        const ni = n[i];

        let value;
        let value_shift;

        if (name === "Coseno discreto") {
            value = A * Math.cos(2*Math.PI*ni/N);
            value_shift = A * Math.cos(2*Math.PI*(ni + N)/N);
        }

        else if (name === "Seno discreto") {
            value = A * Math.sin(2*Math.PI*ni/N);
            value_shift = A * Math.sin(2*Math.PI*(ni + N)/N);
        }

        else if (name === "Suma de armónicos") {
            value = A * (
                Math.cos(2*Math.PI*ni/N)
                + 0.4*Math.cos(4*Math.PI*ni/N)
            );

            value_shift = A * (
                Math.cos(2*Math.PI*(ni + N)/N)
                + 0.4*Math.cos(4*Math.PI*(ni + N)/N)
            );
        }

        else if (name === "Cuadrada discreta") {
            value = A * Math.sign(Math.sin(2*Math.PI*ni/N));
            value_shift = A * Math.sign(Math.sin(2*Math.PI*(ni + N)/N));
        }

        else if (name === "No periódica") {
            value = A * Math.exp(-0.015*ni*ni) * Math.cos(2*Math.PI*ni/N);

            value_shift = A * Math.exp(-0.015*(ni + N)*(ni + N))
                        * Math.cos(2*Math.PI*(ni + N)/N);
        }

        x.push(value);
        x_shift.push(value_shift);
    }

    data["x"] = x;
    data["x_shift"] = x_shift;

    info.text = texts[name];

    source.change.emit();
